mapper.select:
SELECT d.id AS deposit_id, d.deposit_no AS deposit_no, d.community_id AS community_id, d.status AS status, d.balance AS balance, coalesce(sum(t.amount) FILTER (WHERE t.direction = 'I'), 0) AS in_amount, coalesce(sum(t.amount) FILTER (WHERE t.direction = 'O'), 0) AS out_amount, coalesce(sum(t.amount) FILTER (WHERE t.direction = 'D'), 0) AS deduct_amount, coalesce(sum(CASE t.direction WHEN 'I' THEN t.amount WHEN 'O' THEN -t.amount WHEN 'D' THEN -t.amount END), 0) AS calculated FROM deposit d LEFT JOIN deposit_txn t ON t.deposit_id = d.id AND t.tenant_id = d.tenant_id
d.community_id = #{communityId}
GROUP BY d.id, d.deposit_no, d.community_id, d.status, d.balance ORDER BY d.id
